             (Z_to_bv 64 ff) xs3 xs4 xs5 xs6 (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff) xs9 s10 s11 t3' t4' t5' t6')
        F (Z_to_bv 64 P_A_PEV_EXIT) fc None mx (seg_rom bsegs)).
