Lemma pev_mid : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t0' t1' t2' a1' a2' a3' a4' a5' a6' a7' t3' t4' t5' t6' : word)
    (C spa lo shi ff fp : Z) (LF : list fframe) (m m2 : mem) (gap : list cell) (junk p8 lj h32 j216 shb : list byte),
  rw_cells bsegs m2 spa [CB 8 p8; C8 (Z_to_bv 64 ff); CB 24 lj] -> lo + COND_INIT_STACK <= spa ->
  rw_cells bsegs m2 (spa + 40) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -88 - (spa + 40) ->
  (spa = bv_unsigned sp + -128 \/ spa = bv_unsigned sp + -144) ->
  rw_cells bsegs m2 (bv_unsigned sp + -88) (pev_saved s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs m2 ff [CB 32 h32; CB 216 j216; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs m2 (Z.shiftr ff 3 + 2147450880) [CB 32 shb] ->
  rw_cells bsegs m2 fp [C1 (b8 1)] ->
  stk bsegs m2 lo spa -> mem_inv bsegs m2 ->
  as_RFS H ((2, ff, fp) :: LF) m2 -> fresh_frame H LF 2 ff fp -> ACONST m2 -> stack0 m2 lo shi ->
  munch (actor_W H lo sp C ff fp) m m2 -> wmono bsegs m m2 ->
  rw_cells bsegs m2 C [CB 56 junk] -> C mod 8 = 0 -> aapp C 56 -> fsobj H LF C 56 -> accessible m2 C 56 ->
  (C + 56 <= ff \/ ff + 256 <= C) -> (C + 56 <= fp \/ fp + 1 <= C) ->
  AXStatics2 m2 -> ACanaryReads m2 ->
  lo + 144 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (apev_ctor_post H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc C LF lo shi m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0' t1' t2' sp (Z_to_bv 64 spa) (Z_to_bv 64 (C + 48)) a1' a2' a3' a4' a5' a6' a7'
             (Z_to_bv 64 ff) (Z_to_bv 64 C) s4 s5 s6 (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) (Z_to_bv 64 ff)
